import { RefreshToken as e } from "./rft.model.js"; import { verifyRefreshToken as t } from "../../../shared/security/jwt.js"; import r from "../../../shared/errors/AppError.js"; export const storeRefreshToken = async ({ userId: t, jti: o, expiresAt: n, ip: s, userAgent: a, device: i }) => { if (!t || !o || !n) throw new r("Invalid refresh token payload", 500); return e.create({ userId: t, jti: o, expiresAt: n, ip: s, userAgent: a, device: i }) }; export const getValidRefreshToken = async t => { let r = await e.findOne({ jti: t, revokedAt: null, expiresAt: { $gt: new Date } }); return r }; export const revokeRefreshToken = async r => { if (!r) return; let o = t(r); o?.jti && await e.findOneAndUpdate({ jti: o.jti, revokedAt: null }, { revokedAt: new Date }) }; export const revokeAllRefreshTokens = async t => { t && await e.updateMany({ userId: t, revokedAt: null }, { revokedAt: new Date }) }; export const rotateRefreshToken = async ({ oldRefreshTokenJwt: e, newJti: o, userId: n, expiresAt: s, ip: a, userAgent: i }) => { let d = t(e); if (!d?.jti) throw new r("Invalid refresh token", 401); let f = await getValidRefreshToken(d.jti); if (!f) throw await revokeAllRefreshTokens(n), new r("Refresh token reuse detected", 401); return f.revokedAt = new Date, await f.save(), storeRefreshToken({ userId: n, jti: o, expiresAt: s, ip: a, userAgent: i }) };